VALUES ('ai_20', 'msg_20', 'hybrid-workers-ai', 'llama-3.3-70b', 'v2.1', 0.96, '{"primary": "Hi Arif, thank you for your enthusiasm about joining BIAI! Please visit our careers portal at biai.com.bd/careers or email your CV, GitHub/portfolio to hr@biai.com.bd. Our recruitment team reviews internship applications weekly.", "alt": "\u0986\u09b0\u09bf\u09ab \u09ad\u09be\u0987, \u0986\u09ae\u09be\u09a6\u09c7\u09b0 \u0995\u09cd\u09af\u09be\u09b0\u09bf\u09df\u09be\u09b0 \u09aa\u09c7\u099c biai.com.bd/careers \u098f \u0986\u09aa\u09a8\u09be\u09b0 \u09b8\u09bf\u09ad\u09bf \u09b8\u09be\u09ac\u09ae\u09bf\u099f \u0995\u09b0\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u09a8\u0964"}', '{"intent": {"value": "General Course", "confidence": 0.95, "source": "llm"}, "triage": {"value": "CAREERS_HR", "confidence": 0.98, "source": "rule+llm"}, "urgency": {"value": "LOW", "confidence": 0.9, "source": "llm"}, "language": {"value": "EN", "confidence": 1.0, "source": "script_detector"}}', 'PASSED', 1);
